      if (l.state === 'down') { l.state = 'out'; l.t = 0; S.rep = Math.max(0, S.rep - 25); logEvent('🚑 ' + l.who + ' is out cold. An ambulance took them away.', 'bad'); policeFine('You put ' + l.who + ' in hospital'); return; }
