    for (var rg = 0; rg <= 8; rg++) { var ring = new THREE.Mesh(new THREE.TorusGeometry(0.022, 0.005, 6, 12), MAT.chrome); ring.rotation.y = Math.PI / 2; ring.position.set(w * rg / 8, h / 2 + 0.06, 0.05); ring.userData.ringT = rg / 8; g.add(ring); }
