    var m0 = lineup.filter(function (m) { return m.c && lineWaiting(m); })[0]; if (m0) lineSay(m0, pick(['Five minutes. Fine.', 'I\'ll wait.', 'A break? Lucky you.']), '#e8f1ea', 2600);
